/** Decode the lossless grayscale runs generated by scripts/build-mask.mjs. */
export function decodeMask(buffer: ArrayBuffer) {
  const view = new DataView(buffer)
  if (view.byteLength < 8 || (view.byteLength - 8) % 5) throw Error('Invalid mask header')
  const width = view.getUint32(0, true), height = view.getUint32(4, true)
  if (!width || !height || width * height > 16_777_216) throw Error('Invalid mask dimensions')
  const data = new Uint8Array(width * height)
  let offset = 0
  for (let p = 8; p < view.byteLength; p += 5) {
    const length = view.getUint32(p, true)
    if (!length || offset + length > data.length) throw Error('Invalid mask run')
    data.fill(view.getUint8(p + 4), offset, offset + length)
    offset += length
  }
  if (offset !== data.length) throw Error('Incomplete mask')
  return { data, width, height }
}
